return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'hi_IN','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-10-01T20:49:59+00:00','po-revision-date'=>'2026-10-01T20:49:59+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'इस साइट की मीडिया लाइब्रेरी को Zinn® ऑब्जेक्ट स्टोरेज में ले जाता है और इसे CDN से डिलीवर करता है। आपके Zinn® डैशबोर्ड से कॉन्फ़िगर किया गया है — WordPress में कभी कोई एक्सेस कुंजी टाइप नहीं की जाती है।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'सहेजा गया। इसे बदलने के लिए एक नया मान दर्ज करें।','Filter this list…'=>'इस सूची को फ़िल्टर करें…','Filter this list'=>'इस सूची को फ़िल्टर करें','Nothing matches that filter.'=>'उस फ़िल्टर से कुछ भी मेल नहीं खाता।','Add a row'=>'एक पंक्ति जोड़ें','Remove this row'=>'यह पंक्ति हटाएं','Remove'=>'हटाएं','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — विवरण','Overview'=>'अवलोकन','Copied'=>'कॉपी किया गया','Every Zinn® plugin on this site, and whether it is working.'=>'इस साइट पर मौजूद प्रत्येक Zinn® प्लगइन, और वह काम कर रहा है या नहीं।','No connection is needed for this plugin.'=>'इस प्लगइन के लिए किसी कनेक्शन की आवश्यकता नहीं है।','Open settings'=>'सेटिंग्स खोलें','You do not have permission to change these settings.'=>'आपके पास इन सेटिंग्स को बदलने की अनुमति नहीं है।','Settings sections'=>'सेटिंग्स अनुभाग','Support'=>'सहायता','Save changes'=>'परिवर्तन सहेजें','Tools'=>'उपकरण','Export settings'=>'सेटिंग्स निर्यात करें','Reset to defaults'=>'डिफ़ॉल्ट पर रीसेट करें','This puts every setting on this plugin back to its default. Continue?'=>'यह इस प्लगइन की प्रत्येक सेटिंग को उसके डिफ़ॉल्ट पर वापस रीसेट कर देता है। क्या आप जारी रखना चाहते हैं?','Diagnostics for support'=>'सहायता के लिए निदान','Import a settings file'=>'सेटिंग्ज़ फ़ाइल आयात करें','Import'=>'आयात करें','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'निर्यात की गई फ़ाइलों में कभी भी पासवर्ड, टोकन या API कुंजियाँ शामिल नहीं होती हैं — आपको उन्हें नई साइट पर फिर से दर्ज करना होगा।','Settings saved.'=>'सेटिंग्स सहेजी गईं।','Every setting on this plugin is back to its default.'=>'इस प्लगइन की प्रत्येक सेटिंग अपने डिफ़ॉल्ट पर वापस आ गई है।','Done.'=>'पूर्ण हुआ।','That action is not available.'=>'वह क्रिया उपलब्ध नहीं है।','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'वह फ़ाइल पढ़ी नहीं जा सकी। Zinn® प्लगइन से निर्यात की गई सेटिंग्स फ़ाइल चुनें।','That file is too large to be a settings export.'=>'सेटिंग्स निर्यात होने के लिए वह फ़ाइल बहुत बड़ी है।','That file is not a Zinn® settings export.'=>'वह फ़ाइल Zinn® सेटिंग्स निर्यात नहीं है।','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'वह फ़ाइल किसी भिन्न प्लगइन (%s) से निर्यात की गई थी, इसलिए इसे यहाँ आयात करने से वे सेटिंग्स संग्रहीत होंगी जिन्हें यह प्लगइन समझ नहीं पाता है।','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d सेटिंग आयात की गई। पासवर्ड और API कुंजियाँ कभी भी निर्यात में शामिल नहीं होती हैं, इसलिए कृपया उन्हें दोबारा दर्ज करें।' . "\0" . '%d सेटिंग्स आयात की गईं। पासवर्ड और API कुंजियाँ कभी भी निर्यात में शामिल नहीं होती हैं, इसलिए कृपया उन्हें दोबारा दर्ज करें।','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Zinn Digital® ने कोई टोकन वापस नहीं किया। इस साइट पर कुछ भी नहीं बदला गया है।','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'यह साइट अब Zinn® मीडिया ऑफ़लोड से कनेक्ट नहीं है। नए अपलोड इसी सर्वर पर रहेंगे। इसे अपने Zinn Digital® डैशबोर्ड से फिर से युग्मित करें।','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® ने HTTP %d के साथ उत्तर दिया।','Disconnected by Zinn Digital®.'=>'Zinn Digital® द्वारा डिस्कनेक्ट किया गया।','Connected'=>'कनेक्ट हो गया','Connecting…'=>'कनेक्ट हो रहा है…','Connected, but something needs attention'=>'कनेक्ट हो गया, लेकिन कुछ चीज़ों पर ध्यान देने की आवश्यकता है','Not connected'=>'कनेक्ट नहीं है','Running on your own account'=>'आपके अपने खाते पर चल रहा है','We could not check this'=>'हम इसकी जांच नहीं कर सके','This plugin did not say why. Send a diagnostics report and we will look.'=>'इस प्लगइन ने कोई कारण नहीं बताया। एक नैदानिक रिपोर्ट भेजें और हम इसकी जांच करेंगे।','Connection status'=>'कनेक्शन की स्थिति','Last checked %s ago.'=>'अंतिम बार जांच %s पहले की गई।','(opens in a new tab)'=>'(नई टैब में खुलता है)','Send this to Zinn® support'=>'इसे Zinn® सहायता को भेजें','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'बिल्कुल यही भेजा जाएगा — इसके अलावा कुछ नहीं, और कुछ भी छिपा हुआ नहीं है। आपके पासवर्ड, टोकन और API कुंजियाँ इसमें शामिल नहीं हैं।','The diagnostics report that will be sent'=>'डायग्नोस्टिक्स रिपोर्ट जो भेजी जाएगी','Copy to clipboard'=>'क्लिपबोर्ड पर कॉपी करें','Send this report to Zinn® support'=>'यह रिपोर्ट Zinn® सहायता को भेजें','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'हम आपके लिए एक सहायता टिकट खोलते हैं और ईमेल द्वारा उत्तर देते हैं। यदि आप इसे नहीं भेजना चाहते हैं, तो इसे ऊपर से कॉपी करें और स्वयं किसी टिकट में पेस्ट करें।','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'हम इस सर्वर (%s) से Zinn Digital® तक पहुँचने में असमर्थ रहे। ऊपर दी गई रिपोर्ट को कॉपी करें और इसके बजाय एक टिकट खोलें — आपकी सेटिंग्स में कुछ भी गलत नहीं है।','Sent. Zinn® support has your report and will reply by email.'=>'भेज दिया गया। Zinn® सहायता को आपकी रिपोर्ट मिल गई है और वे ईमेल द्वारा उत्तर देंगे।','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'भेज दिया गया। Zinn® सहायता को आपकी रिपोर्ट मिल गई है — संदर्भ %s — और ईमेल द्वारा उत्तर दिया जाएगा।','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'आपने थोड़े ही समय में कई रिपोर्ट भेजी हैं। कुछ मिनट प्रतीक्षा करें और पुनः प्रयास करें — पहले वाली रिपोर्ट प्राप्त हो चुकी हैं।','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® अभी रिपोर्ट स्वीकार नहीं कर सका — यह समस्या हमारी ओर से है, आपकी ओर से नहीं। कृपया थोड़ी देर में पुनः प्रयास करें, या ऊपर दी गई रिपोर्ट को किसी टिकट में कॉपी करें।','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'रिपोर्ट अस्वीकार कर दी गई थी (HTTP %d)। इसे ऊपर कॉपी करें और उस नंबर का हवाला देते हुए एक टिकट खोलें।','%s — guides and services'=>'%s — गाइड और सेवाएँ','User guides'=>'उपयोगकर्ता मार्गदर्शिकाएँ','Read the %s user guide'=>'%s उपयोगकर्ता मार्गदर्शिका पढ़ें','Hide this'=>'इसे छिपाएं','Zinn® hosting for WordPress'=>'WordPress के लिए Zinn® होस्टिंग','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, दैनिक बैकअप, निःशुल्क माइग्रेशन और एक से अधिक साइट चलाने वाले लोगों के लिए बनाया गया एक नियंत्रण कक्ष।','The Zinn® marketplace'=>'Zinn® मार्केटप्लेस','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'स्थापित साइटें, डोमेन और लिंक प्लेसमेंट खरीदें और बेचें, जिसमें पैसा दोनों पक्षों के संतुष्ट होने तक सुरक्षित रखा जाता है।','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — उन लोगों को काम पर रखें जिनका यह पेशा है','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'हमारा वैश्विक फ्रीलांस मार्केटप्लेस: लेखकों, डिज़ाइनरों, डेवलपर्स और एसईओ विशेषज्ञों की 10,000 से अधिक तैयार सेवाओं को ब्राउज़ करें, या एक प्रोजेक्ट पोस्ट करें और उन्हें बोली लगाने दें।','Media Offload'=>'मीडिया ऑफ़लोड','Connection'=>'कनेक्शन','What gets moved'=>'क्या स्थानांतरित किया जाता है','How media is served'=>'मीडिया कैसे परोसा जाता है','Move a batch now'=>'अभी एक बैच स्थानांतरित करें','Media already moved is never affected by a change here — its address does not change.'=>'पहले से स्थानांतरित मीडिया यहाँ किए गए बदलाव से कभी प्रभावित नहीं होता है — इसका पता नहीं बदलता है।','New uploads'=>'नए अपलोड','Move new uploads to Zinn® storage as they arrive'=>'नए अपलोड आते ही उन्हें Zinn® स्टोरेज में ले जाएं','Existing media'=>'मौजूदा मीडिया','Keep moving the media library that is already here'=>'यहाँ पहले से मौजूद मीडिया लाइब्रेरी को स्थानांतरित करना जारी रखें','A few files an hour, in the background, picking up where it left off. Turning this off pauses it; nothing already moved comes back.'=>'पृष्ठभूमि में प्रति घंटे कुछ फ़ाइलें, वहीं से जारी रखते हुए जहाँ यह रुका था। इसे बंद करने पर यह रुक जाता है; पहले से स्थानांतरित की गई कोई भी सामग्री वापस नहीं आती है।','Files per hourly pass'=>'प्रति प्रति घंटा पास फ़ाइलें','Each attachment is several files and every one is a full upload. Raise this on a fast host with a generous execution limit; lower it if passes are being cut short.'=>'प्रत्येक संलग्नक में कई फ़ाइलें होती हैं और प्रत्येक एक पूर्ण अपलोड है। उदार निष्पादन सीमा वाले तेज़ होस्ट पर इसे बढ़ाएं; यदि प्रक्रियाएँ बीच में ही रुक रही हैं तो इसे घटाएं।','Leave files smaller than'=>'इससे छोटी फ़ाइलों को छोड़ दें','Kilobytes. A tiny icon costs more in the extra connection than it saves in disk, so there is rarely a reason to move one. Set to 0 to move everything.'=>'किलोबाइट। एक छोटा आइकन डिस्क में जितनी बचत करता है, उससे अधिक अतिरिक्त कनेक्शन में खर्च करता है, इसलिए इसे स्थानांतरित करने का शायद ही कोई कारण होता है। सब कुछ स्थानांतरित करने के लिए 0 पर सेट करें।','Never move these types'=>'इन प्रकारों को कभी न ले जाएँ','Useful when a plugin reads a file straight off the disk — a font, a PDF a form builder stamps, an audio file a player seeks inside.'=>'तब उपयोगी जब कोई प्लगइन सीधे डिस्क से फ़ाइल पढ़ता है — कोई फ़ॉन्ट, फ़ॉर्म बिल्डर द्वारा स्टैम्प की गई कोई PDF, कोई ऑडियो फ़ाइल जिसके अंदर प्लेयर खोज करता है।','These two are the ones to be careful with — read each description before changing it.'=>'इन दोनों के साथ सावधान रहने की आवश्यकता है — बदलने से पहले प्रत्येक विवरण पढ़ें।','Serve from Zinn® storage'=>'Zinn® स्टोरेज से सर्व करें','Point image and file addresses at Zinn® storage'=>'छवि और फ़ाइल पतों को Zinn® संग्रहण पर इंगित करें','Off, files are uploaded but still served from this server — which is the safe state while you check everything arrived. On, visitors are served from storage and this server stops carrying the traffic.'=>'बंद होने पर, फ़ाइलें अपलोड हो जाती हैं लेकिन फिर भी इसी सर्वर से प्रस्तुत की जाती हैं — जो कि सब कुछ सही से आने की जाँच करते समय सुरक्षित स्थिति है। चालू होने पर, आगंतुकों को स्टोरेज से सामग्री प्रस्तुत की जाती है और यह सर्वर ट्रैफ़िक ले जाना बंद कर देता है।','Free the disk space'=>'डिस्क स्थान खाली करें','Delete the local copy once every size has uploaded'=>'प्रत्येक आकार अपलोड हो जाने के बाद स्थानीय प्रतिलिपि हटाएं','This is the point of offloading, and it is also the irreversible half. Leave it off until “Serve from Zinn® storage” is on and you have checked your site — a local copy is the only thing that saves you if something was missed.'=>'ऑफलोडिंग का उद्देश्य यही है, और यह अपरिवर्तनीय हिस्सा भी है। इसे तब तक बंद रखें जब तक कि “Zinn® स्टोरेज से परोसें” चालू न हो जाए और आप अपनी साइट की जांच न कर लें — यदि कुछ छूट गया हो तो केवल एक स्थानीय प्रति ही आपको बचा सकती है।','Deleting local copies cannot be undone from this screen. Take a backup first — the Zinn® Connector plugin can do that for you.'=>'स्थानीय प्रतियों को हटाना इस स्क्रीन से पूर्ववत नहीं किया जा सकता है। पहले एक बैकअप लें — Zinn® Connector प्लगइन यह आपके लिए कर सकता है।','This site is not connected to Zinn® storage yet, so there is nowhere to move media to.'=>'यह साइट अभी Zinn® स्टोरेज से जुड़ी नहीं है, इसलिए मीडिया को स्थानांतरित करने के लिए कोई जगह नहीं है।','%d attachment moved.'=>'%d अनुलग्नक स्थानांतरित किया गया।' . "\0" . '%d संलग्नक स्थानांतरित किए गए।','This site is not connected to Zinn® storage.'=>'यह साइट Zinn® स्टोरेज से कनेक्ट नहीं है।','Nothing is wrong — it has simply not been paired yet. Media stays on this server until it is.'=>'कुछ भी गलत नहीं है — यह बस अभी तक युग्मित नहीं हुआ है। जब तक यह नहीं हो जाता, मीडिया इसी सर्वर पर रहेगा।','Connected, but the last upload failed.'=>'कनेक्ट हो गया, लेकिन अंतिम अपलोड विफल रहा।','Try a batch now'=>'अभी एक बैच आज़माएँ','Connected. Every attachment has been moved.'=>'कनेक्ट हो गया। प्रत्येक अटैचमेंट को स्थानांतरित कर दिया गया है।','Connected. %1$s of %2$s attachments still on this server.'=>'कनेक्ट हो गया। %2$s में से %1$s अनुलग्नक अभी भी इस सर्वर पर हैं।','Moved so far'=>'अब तक स्थानांतरित','%1$s files, %2$s'=>'%1$s फ़ाइलें, %2$s','Still on this server'=>'अभी भी इस सर्वर पर','%1$s of %2$s attachments'=>'%2$s में से %1$s अटैचमेंट','Served from'=>'यहाँ से प्रस्तुत','this server'=>'यह सर्वर','Connect this site'=>'इस साइट को कनेक्ट करें','Open your Zinn Digital® dashboard, choose this site, open Files & databases, and press “Get a pairing code” under Images & video CDN. Paste the code below.'=>'अपना Zinn Digital® डैशबोर्ड खोलें, इस साइट को चुनें, फ़ाइलें और डेटाबेस खोलें, और छवियाँ और वीडियो CDN के अंतर्गत "पेयरिंग कोड प्राप्त करें" दबाएँ। नीचे कोड पेस्ट करें।','Pairing code'=>'पेयरिंग कोड','Disconnect this site'=>'इस साइट को डिस्कनेक्ट करें','New uploads will stay on this server. Media already moved keeps working — its address does not change.'=>'नए अपलोड इसी सर्वर पर रहेंगे। पहले स्थानांतरित किया गया मीडिया काम करना जारी रखेगा — इसका पता नहीं बदलता है।','You do not have permission to manage this site.'=>'आपके पास इस साइट को प्रबंधित करने की अनुमति नहीं है।','Paste the pairing code from your Zinn Digital® dashboard.'=>'अपने Zinn Digital® डैशबोर्ड से युग्मन कोड चिपकाएँ।','Connected. New uploads will be stored with Zinn Digital® from now on, and your existing media will move in the background.'=>'कनेक्ट हो गया। नए अपलोड अब से Zinn Digital® में संग्रहीत किए जाएंगे, और आपका मौजूदा मीडिया पृष्ठभूमि में स्थानांतरित हो जाएगा।','Disconnected. Media already moved keeps working; new uploads stay on this server.'=>'डिस्कनेक्ट किया गया। पहले से स्थानांतरित किया गया मीडिया काम करना जारी रखेगा; नए अपलोड इसी सर्वर पर रहेंगे।','That file could not be read from this server, so nothing was uploaded.'=>'उस फ़ाइल को इस सर्वर से पढ़ा नहीं जा सका, इसलिए कुछ भी अपलोड नहीं किया गया।','This site could not stream the upload, so nothing was sent.'=>'यह साइट अपलोड को स्ट्रीम नहीं कर सकी, इसलिए कुछ भी नहीं भेजा गया।','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'यह फ़ाइल %1$s है और इस साइट के PHP में cURL नहीं है, इसलिए यह अधिकतम %2$s अपलोड कर सकता है।','The upload could not be completed.'=>'अपलोड पूरा नहीं किया जा सका।','Storage refused the upload (HTTP %d).'=>'स्टोरेज ने अपलोड अस्वीकार कर दिया (HTTP %d)।','Style preset'=>'शैली प्रीसेट','A starting point. Anything below overrides it.'=>'एक शुरुआती बिंदु। नीचे दी गई कोई भी चीज़ इसे अधिलेखित करती है।','Use my own colours and sizes'=>'मेरे अपने रंगों और आकारों का उपयोग करें','Leave this off and the preset is used exactly as it is.'=>'इसे बंद रहने दें और प्रीसेट का उपयोग ठीक वैसे ही किया जाएगा जैसा वह है।','See the Zinn Digital® release notes.'=>'Zinn Digital® रिलीज़ नोट्स देखें।','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Zinn® अपडेट सेवा ने इस अपडेट के लिए डाउनलोड लिंक जारी नहीं किया। जांचें कि क्या यह साइट Zinn® प्लेटफ़ॉर्म तक पहुंच सकती है, फिर पुन: प्रयास करें।','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'अपडेट को Zinn® अपडेट सेवा (%s) से डाउनलोड नहीं किया जा सका। कुछ मिनटों में पुन: प्रयास करें।','The downloaded update failed its integrity check and was not installed.'=>'डाउनलोड किया गया अपडेट अपनी अखंडता जांच में विफल रहा और इंस्टॉल नहीं किया गया।']];